class CurrencyConverter:
    USD_RATE = 1.0
    EUR_RATE = 0.85
    GBP_RATE = 0.72
    JPY_RATE = 110.15
    CAD_RATE = 1.23
    AUD_RATE = 1.34
    CNY_RATE = 6.40

    def __init__(self):
        self.rates = {
            'USD': self.USD_RATE,
            'EUR': self.EUR_RATE,
            'GBP': self.GBP_RATE,
            'JPY': self.JPY_RATE,
            'CAD': self.CAD_RATE,
            'AUD': self.AUD_RATE,
            'CNY': self.CNY_RATE,
        }

    def convert(self, amount, from_currency, to_currency):
        if from_currency == to_currency:
            return amount

        if not self.is_currency_supported(from_currency) or not self.is_currency_supported(to_currency):
            return False

        return self.calculate_converted_amount(amount, from_currency, to_currency)

    def calculate_converted_amount(self, amount, from_currency, to_currency):
        from_rate = self.get_rate(from_currency)
        to_rate = self.get_rate(to_currency)
        converted_amount = (amount / from_rate) * to_rate
        return converted_amount

    def is_currency_supported(self, currency):
        return currency in self.rates

    def get_rate(self, currency):
        return self.rates[currency]

    def get_supported_currencies(self):
        return list(self.rates.keys())

    def add_currency_rate(self, currency, rate):
        if currency in self.rates:
            return False
        self.set_rate(currency, rate)
        return True

    def update_currency_rate(self, currency, new_rate):
        if currency not in self.rates:
            return False
        self.set_rate(currency, new_rate)
        return True

    def set_rate(self, currency, rate):
        self.rates[currency] = rate
